INSERT INTO `sys_api_key` (`id`, `app_name`, `api_key`, `scopes`, `api_secret`, `status`, `remark`, `expire_time`, `last_used_time`, `create_by`, `create_time`) VALUES ('2', '11', 'sk_16a49f8f6dc5c20ca9e8d5d3c651e89697698137', 'user:read', 'b1597d5fe361522a9f2589c41281a241028e1b9728ac14e61d7d7e1a4ee75ad8', '1', '111', '2026-09-30T00:00', NULL, 'admin', '2026-09-06T04:11:13');
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('1', 'pwd.min-length', '密码最小长度', '8', '注册/创建/改密时校验', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('2', 'pwd.require-complex', '密码必须含字母和数字', 'false', 'true=复杂模式', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('3', 'pwd.force-change-initial', '初始/重置密码强制首登修改', 'true', '租户管理员初始密码、管理员重置密码后生效', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('4', 'pwd.expire-days', '密码有效期(天)', '0', '0=永不过期', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('5', 'login.max-attempts', '登录失败锁定阈值', '5', '同账号窗口内连续失败次数', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('6', 'login.lock-minutes', '登录锁定时长(分钟)', '10', '', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('7', 'login.ip-window-max', '单IP登录尝试上限', '30', '10分钟窗口内', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('8', 'captcha.enabled', '图形验证码开关', 'true', '关闭后登录不校验验证码', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('9', 'log.retention-days', '日志保留天数', '90', '0=永久保留，logCleanJob使用', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('10', 'login.2fa-enabled', '两步认证总开关', 'true', '关闭后即使已绑定也不校验动态码', NULL, NULL);
INSERT INTO `sys_config` (`id`, `config_key`, `config_name`, `config_value`, `remark`, `update_by`, `update_time`) VALUES ('11', 'login.max-sessions-per-user', '单账号最大在线设备数', '3', '0=不限制，超限自动下线最旧设备', NULL, NULL);
